// SUCCEED source template adapted with a Notes column.
const s4Template = {"wordParts": {"[Content_Types].xml": "", "_rels/.rels": "", "word/document.xml": "", "word/_rels/document.xml.rels": "", "word/footnotes.xml": "", "word/endnotes.xml": "", "word/header1.xml": "", "word/header2.xml": "", "word/header3.xml": "", "word/_rels/header2.xml.rels": "", "word/media/image1.png": "", "word/theme/theme1.xml": "", "word/settings.xml": "", "customXml/item1.xml": "", "customXml/itemProps1.xml": "", "word/styles.xml": "", "word/webSettings.xml": "", "word/fontTable.xml": "", "docProps/core.xml": "", "docProps/app.xml": "", "customXml/_rels/item1.xml.rels": "", "word/footer-succeed.xml": ""}, "source": "https://equator-network.org/reporting-guidelines/succeed/SUCCEED_checklist.docx", "rows": [{"id": "S1", "group": "Title and abstract", "labels": ["Title", "Study identification"], "recommendation": "Compose a title that includes the study design, the intervention to be scaled, the population, and the condition or primary issue addressed."}, {"id": "S2", "group": "Title and abstract", "labels": ["Abstract"], "recommendation": "Provide an abstract that can be structured or not but should include background, study design, aim, methods, results, and conclusion. It should describe the intervention to be scaled, the primary issue it addresses, and the contexts (e.g., high income countries/low and middle income countries, rural/urban) of both the original intervention and the scaling setting. It should justify scaling, name the scaling approach (e.g., horizontal, vertical), target (population or setting), dimension (e.g., number of sites/units), principal scaling strategy, main outcome/s and dates of scaling implementation."}, {"id": "S3a", "group": "Introduction", "labels": ["Background", "Scientific background"], "recommendation": "State the research question and its scientific background (e.g., the problem, challenge, or deficiency in healthcare or public health) that scaling the intervention addresses."}, {"id": "S3b", "group": "Introduction", "labels": ["Background", "Justification"], "recommendation": "Provide the justification for scaling: Why scale? What is the strength of the evidence? Weigh up positive and negative impacts. Who/what are the people and places that will be affected by scaling and how will they be affected? Does scaling address equity? Where relevant, indicate whether sex and/or gender differences may affect the impact of scaling."}, {"id": "S4", "group": "Introduction", "labels": ["Aim and objectives"], "recommendation": "State the aim and objectives of the scaling study and, where applicable, the objectives of the intervention being scaled."}, {"id": "S5", "group": "Methods", "labels": ["Study design"], "recommendation": "Identify the study design chosen and why. Indicate where the protocol can be accessed, if available."}, {"id": "S6", "group": "Methods", "labels": ["Theoretical framework"], "recommendation": "Report the use of a theoretical framework, where applicable."}, {"id": "S7", "group": "Methods", "labels": ["Targeted participants"], "recommendation": "Describe the targeted units of scaling (who/what are the people, places, organizations and/or other things that were targeted by the scaling process), and the associated eligibility criteria."}, {"id": "S8a", "group": "Methods", "labels": ["Context", "Intervention"], "recommendation": "Specify the context (e.g., setting) where the evidence-informed health intervention to be scaled was developed."}, {"id": "S8b", "group": "Methods", "labels": ["Context", "Scaling"], "recommendation": "Specify the context (e.g., setting) of the scaling study."}, {"id": "S9a", "group": "Methods", "labels": ["Description of the evidence-informed health intervention", "Functions and forms of the health intervention"], "recommendation": "Describe the health intervention, distinguishing between the adaptable periphery (forms) and core functions (i.e., identifying modifiable, and non-modifiable elements). Be careful to distinguish the health intervention from the scaling strategy."}, {"id": "S9b", "group": "Methods", "labels": ["Description of the evidence-informed health intervention", "Scalability assessment"], "recommendation": "Provide information on any evaluation of the potential of the health intervention for scaling, with appropriate bibliographic references. Provide a summary of key elements of the assessment (e.g., acceptability, effectiveness)."}, {"id": "S10", "group": "Methods", "labels": ["Description and delivery of scaling strategy"], "recommendation": "Describe the scaling approach (e.g., horizontal or vertical), and the scaling strategy, i.e., the plan for managing the scaling process. Describe the delivery (frequency, duration, intensity, mode), including targeted infrastructure, resource team or organization."}, {"id": "S11", "group": "Methods", "labels": ["Engagement"], "recommendation": "Document how the decision to scale the intervention was made and who is scaling it. Describe community partners in the scaling project and their respective roles. Document their levels of involvement, and their respective expectations. Report on how engagement was coordinated and if there was consensus."}, {"id": "S12a", "group": "Methods", "labels": ["Outcomes", "Health intervention"], "recommendation": "Describe the outcomes of the health intervention being scaled."}, {"id": "S12b", "group": "Methods", "labels": ["Outcomes", "Scaling"], "recommendation": "Describe the outcomes of the scaling strategy including the quantitative and/or qualitative definition of success, e.g., coverage (reach, adoption), harm, impact, implementation, maintenance, fidelity, cost, barriers and facilitators."}, {"id": "S13", "group": "Methods", "labels": ["Analysis"], "recommendation": "Describe the types of analysis pertaining to outcomes of both the health intervention and the scaling strategy, including relevant subgroup analyses. If numbers are sufficient, for equity purposes, consider sociocultural subgroup analyses (e.g., context, age, sex, gender, education, ethnicity, income level disability, and other intersecting factors)."}, {"id": "S14", "group": "Results", "labels": ["Participants"], "recommendation": "Describe the essential characteristics of the participants (actors, targeted recipients) at different levels of study involvement. Report on size of community organizations and whether for-profit or not; age, sex, gender, income, education, ethnicity of individuals (e.g., patients, health professionals); roles and disciplines in leadership teams. If relevant, subject participant data should be presented disaggregated by age, sex, gender, and other intersecting factors."}, {"id": "S15a", "group": "Results", "labels": ["Outcomes", "Effectiveness of the scaled health intervention"], "recommendation": "Report the effectiveness outcomes of the scaled health intervention, if measured. Comparisons with outcomes of the original intervention should be reported, where applicable."}, {"id": "S15b", "group": "Results", "labels": ["Outcomes", "Scaling"], "recommendation": "Report on outcomes specific to the scaling strategy, e.g., effective coverage (adoption, reach), implementation, and equity, using the appropriate numerators and denominators where feasible. Barriers and facilitators of scaling should also be reported."}, {"id": "S15c", "group": "Results", "labels": ["Outcomes", "Cost/economic analysis"], "recommendation": "Document the cost of the health intervention and the cost of scaling it."}, {"id": "S15d", "group": "Results", "labels": ["Outcomes", "Fidelity and adaptation"], "recommendation": "Report fidelity to core functions of the health intervention and planned scaling strategy. Document reasons for and impact of any adaptations to the original intervention for different target populations, localities, or organizational cultures."}, {"id": "S15e", "group": "Results", "labels": ["Outcomes", "Unintended consequences"], "recommendation": "Report unintended consequences such as unexpected benefits, harms, failures or costs."}, {"id": "S15f", "group": "Results", "labels": ["Outcomes", "Sustainability"], "recommendation": "Specify sustainability factors and mechanisms put in place to support sustainability after scaling."}, {"id": "S16a", "group": "Discussion", "labels": ["Summary of results"], "recommendation": "Summarize key results related to the primary outcome and success or failure of scaling."}, {"id": "S16b", "group": "Discussion", "labels": ["Explanation of results"], "recommendation": "Explain important results and compare them to results of the original intervention, to results in similar scaling studies, and to other relevant evidence. Where applicable, reflect on adaptations or trade-offs made for optimal scale."}, {"id": "S16c", "group": "Discussion", "labels": ["Study limitations"], "recommendation": "Discuss limitations of the study."}, {"id": "S16d", "group": "Discussion", "labels": ["Implications"], "recommendation": "Mention any implications of the scaling strategy and/or health intervention for policy and practice."}, {"id": "S17a", "group": "Other information", "labels": ["Funding source"], "recommendation": "Mention the sources of funding that supported the study and their role, if any."}, {"id": "S17b", "group": "Other information", "labels": ["Conflict of interest"], "recommendation": "State potential interests of individuals in the outcomes of the study and any conflict of interest."}, {"id": "S17c", "group": "Other information", "labels": ["Ethics review"], "recommendation": "Report whether the study was approved by a research ethics committee. Identify the review committee(s) or justify any waiver."}, {"id": "S18a", "group": "Other information", "labels": ["Open science practices", "Registration"], "recommendation": "Indicate if the study is registered and give registration details if applicable (e.g. registry name, registration number or identifier)."}, {"id": "S18b", "group": "Other information", "labels": ["Open science practices", "Data sharing"], "recommendation": "Indicate whether study data will be available and how it can be accessed."}], "widths": [62, 100, 48, 332, 65, 150.8], "logo": ""};
